with metrics_long as (select * from (select id, device_code, pressure, humidity, temp_c from device_readings) src unpivot include nulls (value for measure in (pressure as PRESSURE_VAL, humidity, temp_c))) select device_code, case when value >= 83 then 'HIGH' else 'LOW' end as value_tier, count(*) as num_rows, percentile_approx(value, 0.95) as value_p95, approx_percentile(value, 0.9) as value_p90, round(avg(value), 2) as avg_value, percentile_approx(value, 0.5) as value_p50, sum(value) filter (where measure = 'temp_c') as temp_c_total_value from metrics_long group by rollup (device_code, case when value >= 83 then 'HIGH' else 'LOW' end);
